import subprocess


def execute_shell_command(cmd):
    out = ""
    err = ""
    rc = 0
    try:
        p = subprocess.Popen(
            cmd,
            shell=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            executable="/bin/bash",
        )
        cout, cerr = p.communicate()
        if cout is not None:
            out = cout.decode("utf-8", "ignore")
        if cerr is not None:
            err = cerr.decode("utf-8", "ignore")
        rc = p.returncode
    except Exception as exc:
        err = f"Shell command exception: {cmd}: {exc}"
        rc = 1
    return (out, err, rc)


def execute_sudo_command(cmd):
    cmd = f"sudo {cmd}"
    return execute_shell_command(cmd)
